'use client';

/**
 * <RoxyHexagram data={...} /> — I Ching hexagram with trigram glyphs, judgment, image, and changing lines.
 *
 * You own this file. Customize freely. The underlying Lit element loads
 * from jsDelivr at runtime via @roxyapi/ui-react, so updates ship without
 * a re-install.
 *
 * Typical wiring (server-side fetch, client-side render):
 *
 * ```ts
 * // app/api/hexagram/route.ts
 * import { createRoxy } from '@roxyapi/sdk';
 * const roxy = createRoxy(process.env.ROXY_API_KEY!);
 * export async function POST(req: Request) {
 *   const { data } = await roxy.iching.castReading();
 *   return Response.json(data);
 * }
 * ```
 *
 * Theme via --roxy-* CSS custom properties on :root (see globals.css).
 */
import { RoxyHexagram as Element } from '@roxyapi/ui-react';
import type { ComponentProps } from 'react';

export type RoxyHexagramProps = ComponentProps<typeof Element>;

export function RoxyHexagram(props: RoxyHexagramProps) {
	return <Element {...props} />;
}

export default RoxyHexagram;
